hunks.new:
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts = 0;
    let mut delay = config.base_delay_ms;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= config.max_attempts => {
                return Err(error)
            }
            Err(error) => {
                sleeper.sleep_ms(delay.min(config.max_delay_ms));
                delay = delay
                    .checked_mul(2)
                    .unwrap_or(config.max_delay_ms)
                    .min(config.max_delay_ms);
                let _ = error;
            }
        }
    }
}

